//! Shared Rust/WASM vector for root-holder enrollment authoring (#379, #381).
//!
//! `tests/fixtures/enrollment_vector.json` holds device keys generated by Node's own X25519 and
//! Ed25519 (not this crate), fingerprints computed by Node's SHA-256 over the documented preimage,
//! and the outcome each case must have, written from `docs/enrollment.md` and the
//! [`allw_core::enrollment`] module docs. This test runs every case through the core. The same
//! fixture goes through the compiled `.wasm` in `packages/sdk/test/enrollment-vector.test.mjs`, so
//! `allw-approver pair` / `vouch` (which call the WASM) refuse exactly what the core refuses.
//!
//! @see ../../../docs/enrollment.md §Interim vouching
//! @see https://datatracker.ietf.org/doc/html/rfc7748#section-5 (X25519 encoding)
//! @see https://datatracker.ietf.org/doc/html/rfc8032#section-5.1.3 (Ed25519 point decoding)

use std::collections::BTreeMap;
use std::path::PathBuf;

use allw_core::{
    account_id_for_root, device_key_fingerprint, next_account_state, sign_account_state,
    AccountState, AccountStateChange, AccountStateDevice, AccountStateRevocation,
    AccountStateRevocationKind, DeviceEnrollment, DeviceKeyKind, DeviceMaterialError,
    NextAccountStateError, SigningKeyPair,
};
use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine};
use serde::Deserialize;

const ROOT_SEED: [u8; 32] = [0x11; 32];
const OTHER_ROOT_SEED: [u8; 32] = [0x33; 32];

#[derive(Deserialize)]
struct Keys {
    encryption_pubkey: String,
    signing_pubkey: String,
}

#[derive(Deserialize)]
struct MaterialCase {
    name: String,
    device_id: String,
    encryption_pubkey: String,
    signing_pubkey: String,
    error: Option<String>,
}

#[derive(Deserialize)]
struct FingerprintCase {
    kind: String,
    key: String,
    fingerprint: String,
}

#[derive(Deserialize)]
struct DeviceRef {
    id: String,
    key: String,
    status: String,
}

#[derive(Deserialize)]
struct StateCase {
    sequence: u64,
    devices: Vec<DeviceRef>,
    revocations: Vec<String>,
    signed_by: String,
}

#[derive(Deserialize)]
struct AddRef {
    id: String,
    key: String,
}

#[derive(Deserialize)]
struct Expect {
    sequence: u64,
    devices: Vec<(String, String, String)>,
}

#[derive(Deserialize)]
struct NextStateCase {
    name: String,
    states: Vec<StateCase>,
    relay_max_sequence: u64,
    floor: u64,
    add: AddRef,
    error: Option<String>,
    expect: Option<Expect>,
}

#[derive(Deserialize)]
struct Fixture {
    keys: BTreeMap<String, Keys>,
    material: Vec<MaterialCase>,
    fingerprints: Vec<FingerprintCase>,
    next_state: Vec<NextStateCase>,
}

fn fixture() -> Fixture {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("enrollment_vector.json");
    serde_json::from_str(&std::fs::read_to_string(path).expect("read the enrollment fixture"))
        .expect("parse the enrollment fixture")
}

fn b32(text: &str) -> [u8; 32] {
    URL_SAFE_NO_PAD
        .decode(text)
        .expect("fixture base64url")
        .try_into()
        .expect("fixture keys are 32 bytes")
}

fn material_error_name(e: DeviceMaterialError) -> &'static str {
    match e {
        DeviceMaterialError::InvalidDeviceId => "InvalidDeviceId",
        DeviceMaterialError::KeyEncoding(DeviceKeyKind::Encryption) => "KeyEncoding(Encryption)",
        DeviceMaterialError::KeyEncoding(DeviceKeyKind::Signing) => "KeyEncoding(Signing)",
        DeviceMaterialError::NonCanonicalEncryptionKey => "NonCanonicalEncryptionKey",
        DeviceMaterialError::SmallOrderEncryptionKey => "SmallOrderEncryptionKey",
        DeviceMaterialError::InvalidSigningKey => "InvalidSigningKey",
        DeviceMaterialError::WeakSigningKey => "WeakSigningKey",
        _ => "unknown",
    }
}

fn next_error_name(e: &NextAccountStateError) -> &'static str {
    match e {
        NextAccountStateError::AccountState(_) => "AccountState",
        NextAccountStateError::UnbackedMaxSequence { .. } => "UnbackedMaxSequence",
        NextAccountStateError::BelowFloor { .. } => "BelowFloor",
        NextAccountStateError::ConflictingStates { .. } => "ConflictingStates",
        NextAccountStateError::DeviceRevoked { .. } => "DeviceRevoked",
        NextAccountStateError::DeviceKeyMismatch { .. } => "DeviceKeyMismatch",
        NextAccountStateError::AlreadyActive { .. } => "AlreadyActive",
        NextAccountStateError::KeysRevoked { .. } => "KeysRevoked",
        NextAccountStateError::KeyConflict { .. } => "KeyConflict",
        NextAccountStateError::TooManyDevices { .. } => "TooManyDevices",
        NextAccountStateError::TooManyAccountStates { .. } => "TooManyAccountStates",
        NextAccountStateError::AccountIdMismatch => "AccountIdMismatch",
        NextAccountStateError::SequenceOverflow => "SequenceOverflow",
        _ => "unknown",
    }
}

#[test]
fn device_material_cases() {
    let fx = fixture();
    for case in &fx.material {
        let result = DeviceEnrollment::parse(
            &case.device_id,
            &case.encryption_pubkey,
            &case.signing_pubkey,
        );
        match (&case.error, result) {
            (None, Ok(_)) => {}
            (Some(expected), Err(e)) => {
                assert_eq!(material_error_name(e), expected, "{}", case.name);
            }
            (expected, got) => panic!("{}: expected {expected:?}, got {got:?}", case.name),
        }
    }
}

#[test]
fn fingerprints_match_the_independent_computation() {
    let fx = fixture();
    for case in &fx.fingerprints {
        let kind = match case.kind.as_str() {
            "encryption" => DeviceKeyKind::Encryption,
            _ => DeviceKeyKind::Signing,
        };
        assert_eq!(
            device_key_fingerprint(kind, &b32(&case.key)),
            case.fingerprint,
            "{} {}",
            case.kind,
            case.key
        );
    }
}

#[test]
fn next_account_state_cases() {
    let fx = fixture();
    let root = SigningKeyPair::from_seed(&ROOT_SEED);
    let other = SigningKeyPair::from_seed(&OTHER_ROOT_SEED);
    let account_id = account_id_for_root(&root.public_key());
    let device = |r: &DeviceRef| AccountStateDevice {
        device_id: r.id.clone(),
        encryption_pubkey: b32(&fx.keys[&r.key].encryption_pubkey),
        signing_pubkey: b32(&fx.keys[&r.key].signing_pubkey),
        status: r.status.clone(),
        cert_expires_at: None,
    };
    for case in &fx.next_state {
        let docs: Vec<String> = case
            .states
            .iter()
            .map(|s| {
                let state = AccountState {
                    v: 1,
                    account_id: account_id.clone(),
                    sequence: s.sequence,
                    current_root: root.public_key().to_bytes(),
                    previous_roots: vec![],
                    devices: s.devices.iter().map(device).collect(),
                    actors: vec![],
                    revocations: s
                        .revocations
                        .iter()
                        .map(|id| AccountStateRevocation {
                            kind: AccountStateRevocationKind::Device,
                            id: id.clone(),
                            revoked_at: 1_700_000_000_000,
                            reason: None,
                        })
                        .collect(),
                };
                sign_account_state(
                    &state,
                    if s.signed_by == "other" {
                        &other
                    } else {
                        &root
                    },
                )
            })
            .collect();
        let refs: Vec<&str> = docs.iter().map(String::as_str).collect();
        let keys = &fx.keys[&case.add.key];
        let change = AccountStateChange::AddDevice(
            DeviceEnrollment::parse(&case.add.id, &keys.encryption_pubkey, &keys.signing_pubkey)
                .expect("fixture devices are valid"),
        );
        let result = next_account_state(
            &refs,
            case.relay_max_sequence,
            case.floor,
            &account_id,
            &root.public_key(),
            &change,
        );
        match (&case.error, result) {
            (None, Ok(next)) => {
                let expect = case.expect.as_ref().expect("a success case has `expect`");
                assert_eq!(next.sequence, expect.sequence, "{}", case.name);
                let got: Vec<(String, [u8; 32], [u8; 32], String)> = next
                    .devices
                    .iter()
                    .map(|d| {
                        (
                            d.device_id.clone(),
                            d.encryption_pubkey,
                            d.signing_pubkey,
                            d.status.clone(),
                        )
                    })
                    .collect();
                let want: Vec<(String, [u8; 32], [u8; 32], String)> = expect
                    .devices
                    .iter()
                    .map(|(id, key, status)| {
                        (
                            id.clone(),
                            b32(&fx.keys[key].encryption_pubkey),
                            b32(&fx.keys[key].signing_pubkey),
                            status.clone(),
                        )
                    })
                    .collect();
                assert_eq!(got, want, "{}", case.name);
            }
            (Some(expected), Err(e)) => {
                assert_eq!(next_error_name(&e), expected, "{}", case.name);
            }
            (expected, got) => panic!("{}: expected {expected:?}, got {got:?}", case.name),
        }
    }
}
